name: Build any cpu

on:
  workflow_call:
    inputs: &common_inputs
      preset:
        type: string
        default: 'cpu'
      deploy:
        type: boolean
      llamacpp_repo:
        type: string
      llamacpp_version:
        type: string
      llamacpp_commit:
        type: string
      boringssl_repo:
        type: string
      boringssl_version:
        type: string

  workflow_dispatch:
    inputs: *common_inputs

permissions:
  contents: read

jobs:
  build:
    runs-on: ubuntu-latest

    steps:
      - uses: actions/checkout@v5

      - name: Setup Zig
        run: python scripts/install-zig.py

      - name: Setup Java
        if: ${{ contains(inputs.preset, '-windows-') }}
        uses: actions/setup-java@v6
        with:
          distribution: zulu
          java-version: "25"

      - name: Build ${{ inputs.preset }}
        env:
          LLAMACPP_REPO: ${{ inputs.llamacpp_repo }}
          LLAMACPP_COMMIT: ${{ inputs.llamacpp_commit }}
          BORINGSSL_REPO: ${{ inputs.boringssl_repo }}
          BORINGSSL_VERSION: ${{ inputs.boringssl_version }}
          HF_TOKEN: ${{ secrets.HF_TOKEN_READ }}
          HF_REPO: ${{ vars.HF_REPO }}
          PRESET: ${{ inputs.preset }}
          AZURE_TENANT_ID: ${{ secrets.AZURE_TENANT_ID }}
          AZURE_CLIENT_ID: ${{ secrets.AZURE_CLIENT_ID }}
          AZURE_CLIENT_SECRET: ${{ secrets.AZURE_CLIENT_SECRET }}
          AZURE_TS_ENDPOINT: ${{ secrets.AZURE_TS_ENDPOINT }}
          AZURE_TS_ACCOUNT_NAME: ${{ secrets.AZURE_TS_ACCOUNT_NAME }}
          AZURE_TS_PROFILE_NAME: ${{ secrets.AZURE_TS_PROFILE_NAME }}
        run: cmake --workflow --preset "$PRESET"

      - name: Deploy
        if: ${{ inputs.deploy && vars.HF_REPO != '' }}
        env:
          HF_TOKEN: ${{ secrets.HF_TOKEN }}
          HF_REPO: ${{ vars.HF_REPO }}
          VERSION: ${{ inputs.llamacpp_version }}
        run: |
          pip install -U huggingface_hub
          python scripts/upload.py "$HF_REPO/$VERSION"

name: Build any windows rocm

on:
  workflow_call:
    inputs: &common_inputs
      preset:
        type: string
        default: 'x86_64-windows-rocm-gfx1100'
      deploy:
        type: boolean
      llamacpp_repo:
        type: string
      llamacpp_version:
        type: string
      llamacpp_commit:
        type: string
      boringssl_repo:
        type: string
      boringssl_version:
        type: string

  workflow_dispatch:
    inputs: *common_inputs

permissions:
  contents: read

jobs:
  build:
    runs-on: windows-2022
    env:
      ROCM_VERSION: "10.2.0a20261015"

    steps:
      - uses: actions/checkout@v5

      - name: Setup windows env
        uses: ilammy/msvc-dev-cmd@v1
        with:
          arch: x64

      - name: Install rocm
        env:
          PRESET: ${{ inputs.preset }}
        run: |
          $Gfx = "$env:PRESET".Split('-')[-1]
          $Rocm = switch -Wildcard ($Gfx) {
            ('probe') { "rocm[devel,libraries]" }
            ('gfx*')  { "rocm[devel,libraries,device-$Gfx]" }
            default   { "rocm[devel,libraries,device-all]" }
          }
          pip install --extra-index-url https://nightly.repo.amd.com/rocm/whl-next/ "$Rocm==$env:ROCM_VERSION"
          rocm-sdk init
          $Root = rocm-sdk path --root
          "ROCM_PATH=$Root" >> $env:GITHUB_ENV
          "HIP_PATH=$Root" >> $env:GITHUB_ENV
          "HIP_DEVICE_LIB_PATH=$Root\lib\llvm\amdgcn\bitcode" >> $env:GITHUB_ENV

      - name: Setup Java
        uses: actions/setup-java@v6
        with:
          distribution: zulu
          java-version: "25"

      - name: Build ${{ inputs.preset }}
        env:
          LLAMACPP_REPO: ${{ inputs.llamacpp_repo }}
          LLAMACPP_COMMIT: ${{ inputs.llamacpp_commit }}
          BORINGSSL_REPO: ${{ inputs.boringssl_repo }}
          BORINGSSL_VERSION: ${{ inputs.boringssl_version }}
          HF_TOKEN: ${{ secrets.HF_TOKEN_READ }}
          HF_REPO: ${{ vars.HF_REPO }}
          PRESET: ${{ inputs.preset }}
          AZURE_TENANT_ID: ${{ secrets.AZURE_TENANT_ID }}
          AZURE_CLIENT_ID: ${{ secrets.AZURE_CLIENT_ID }}
          AZURE_CLIENT_SECRET: ${{ secrets.AZURE_CLIENT_SECRET }}
          AZURE_TS_ENDPOINT: ${{ secrets.AZURE_TS_ENDPOINT }}
          AZURE_TS_ACCOUNT_NAME: ${{ secrets.AZURE_TS_ACCOUNT_NAME }}
          AZURE_TS_PROFILE_NAME: ${{ secrets.AZURE_TS_PROFILE_NAME }}
        run: cmake --workflow --preset "$env:PRESET"

      - name: Deploy
        if: ${{ inputs.deploy && vars.HF_REPO != '' }}
        env:
          HF_TOKEN: ${{ secrets.HF_TOKEN }}
          HF_REPO: ${{ vars.HF_REPO }}
          VERSION: ${{ inputs.llamacpp_version }}
        run: |
          pip install -U huggingface_hub
          python scripts/upload.py "$env:HF_REPO/$env:VERSION"

