import io
import json
import os
import platform
import shutil
import sys
import tarfile
import time
import zipfile
from concurrent.futures import ThreadPoolExecutor, as_completed
from functools import wraps
from pathlib import Path
from urllib.request import urlopen

from versions import CUDA_VERSIONS

URL = "https://developer.download.nvidia.com/compute/cuda/redist"

def cuda_version():
    code = os.getenv("CUDA_CODE")
    if code in CUDA_VERSIONS:
        return CUDA_VERSIONS[code]
    codes = ", ".join(sorted(CUDA_VERSIONS))
    sys.exit(f"Unknown CUDA_CODE '{code}' (expected one of: {codes})")

VERSION = cuda_version()

ROOT = Path.cwd() / "deps" / "cuda"
DEST = ROOT.with_suffix(".tmp")

COMPONENTS = [
    ("libcublas",      "target", None, None),
    ("cuda_cudart",    "target", None, None),
    ("cuda_cccl",      "target", None, lambda m: "cccl" if "cccl" in m else "cuda_cccl"),
    ("cuda_crt",       "target", lambda m, t: "cuda_crt" in m, None),
    ("libnvvm",        "host",   lambda m, t: "libnvvm" in m, None),
    ("cuda_nvcc",      "host",   None, None),
    ("cuda_nvprune",   "host",   lambda m, t: t == "linux", None),
    ("cuda_cuobjdump", "host",   lambda m, t: t == "linux", None),
]

def retry(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        for i in reversed(range(5)):
            try:
                return func(*args, **kwargs)
            except Exception:
                if not i:
                    raise
                time.sleep(10)
    return wrapper

def detect_arch():
    machine = platform.machine().lower()
    if machine in ("x86_64", "amd64"):
        return "x86_64"
    if machine in ("aarch64", "arm64"):
        return "aarch64"
    return machine

def detect_os():
    system = platform.system().lower()
    return {"darwin": "macos"}.get(system, system)

def platform_key(arch, os_name):
    if os_name == "linux":
        return {"x86_64": "linux-x86_64", "aarch64": "linux-sbsa"}[arch]

    if os_name == "windows":
        return {"x86_64": "windows-x86_64", "aarch64": "windows-arm64"}[arch]

    sys.exit(f"Unsupported OS: {os_name}")

def strip_top(path):
    parts = Path(path).parts
    return str(Path(*parts[1:])) if len(parts) > 1 else ""

def _extract_zip(data, dest):
    with zipfile.ZipFile(io.BytesIO(data)) as z:
        for member in z.infolist():
            rel = strip_top(member.filename)
            if not rel or member.is_dir():
                continue
            target = dest / rel
            target.parent.mkdir(parents=True, exist_ok=True)
            with z.open(member) as src, open(target, "wb") as dst:
                shutil.copyfileobj(src, dst)

def _extract_tar(data, dest):
    with tarfile.open(fileobj=io.BytesIO(data), mode="r:*") as tar:
        members = []
        for member in tar.getmembers():
            rel = strip_top(member.name)
            if not rel:
                continue
            member.name = rel
            members.append(member)
        tar.extractall(dest, members=members, filter="tar")

def make_task(manifest, component, key, plat):
    data = manifest[key(manifest) if key else component]
    label = f"{data['name']} version {data['version']} ({plat})"
    return (label, data[plat]["relative_path"])

def collect_tasks(manifest, target_plat, host_plat, target_os):
    tasks = []
    for name, which, gate, key in COMPONENTS:
        if gate is not None and not gate(manifest, target_os):
            continue
        plat = target_plat if which == "target" else host_plat
        tasks.append(make_task(manifest, name, key, plat))
    return tasks

@retry
def download_manifest():
    with urlopen(f"{URL}/redistrib_{VERSION}.json", timeout=60) as r:
        return json.load(r)

@retry
def install_component(name, file):
    with urlopen(f"{URL}/{file}", timeout=120) as r:
        data = r.read()

    if file.endswith(".zip"):
        _extract_zip(data, DEST)
    else:
        _extract_tar(data, DEST)

    return f" - {name}"

def main():
    arch = sys.argv[1] if len(sys.argv) >= 2 else detect_arch()
    target_os = sys.argv[2] if len(sys.argv) >= 3 else os.getenv("CUDA_TARGET_OS", detect_os())

    host_os = detect_os()
    host_plat = platform_key(arch, host_os)
    target_plat = platform_key(arch, target_os)

    cross = host_os != target_os
    print(f"Installing CUDA {VERSION} (arch={arch}, target={target_os}"
          f"{f', host={host_os}' if cross else ''})...")

    manifest = download_manifest()
    tasks = collect_tasks(manifest, target_plat, host_plat, target_os)

    shutil.rmtree(DEST, ignore_errors=True)
    DEST.mkdir(parents=True)

    with ThreadPoolExecutor(2) as pool:
        futures = [pool.submit(install_component, name, file) for name, file in tasks]
        for f in as_completed(futures):
            print(f.result())

    DEST.rename(ROOT)

    if target_os == "linux":
        (ROOT / "lib64").symlink_to("lib")


if __name__ == "__main__":
    main()

import sys
import time
import zipfile
import tempfile
from urllib.request import urlopen, Request
import tarfile
import shutil
import platform
from functools import wraps
from pathlib import Path
from versions import ZIG_VERSION as VERSION

ROOT = Path.cwd() / "deps" / "zig"
DEST = ROOT.with_suffix(".tmp")

URL = "https://zigmirror.com"

def retry(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        for i in reversed(range(5)):
            try:
                return func(*args, **kwargs)
            except Exception:
                if not i:
                    raise
                time.sleep(10)
    return wrapper

def detect_arch():
    machine = platform.machine().lower()
    if machine in ["x86_64", "amd64"]:
        return "x86_64"
    if machine in ["aarch64", "arm64"]:
        return "aarch64"
    return machine

def detect_os():
    system = platform.system()
    if system == "Linux":
        return "linux"
    if system == "Windows":
        return "windows"
    if system == "Darwin":
        return "macos"
    return system.lower()

def fetch(file):
    req = Request(f"{URL}/{file}", headers={"User-Agent": "curl/8.0"})
    return urlopen(req, timeout=60)

def strip_top(member_name):
    parts = Path(member_name).parts
    if len(parts) > 1:
        return str(Path(*parts[1:]))
    return None

@retry
def install_tar(file):
    def members(tar):
        for member in tar:
            name = strip_top(member.name)
            if name:
                member.name = name
                yield member

    with fetch(file) as r:
        with tarfile.open(fileobj=r, mode="r|*") as tar:
            tar.extractall(DEST, members=members(tar), filter='tar')

@retry
def install_zip(file):
    with fetch(file) as r, tempfile.NamedTemporaryFile(suffix=".zip") as tmp:
        shutil.copyfileobj(r, tmp)
        tmp.flush()
        with zipfile.ZipFile(tmp) as z:
            for info in z.infolist():
                name = strip_top(info.filename)
                if not name or info.is_dir():
                    continue
                target = DEST / name
                target.parent.mkdir(parents=True, exist_ok=True)
                with z.open(info) as src, open(target, "wb") as dst:
                    shutil.copyfileobj(src, dst)

def main():
    arch = sys.argv[1] if len(sys.argv) >= 2 else detect_arch()
    osname = detect_os()

    if osname == "windows":
        file = f"zig-{arch}-windows-{VERSION}.zip"
        install = install_zip
    else:
        file = f"zig-{arch}-{osname}-{VERSION}.tar.xz"
        install = install_tar

    shutil.rmtree(DEST, ignore_errors=True)
    DEST.mkdir(parents=True)

    print(f"Installing Zig {VERSION} ({arch}/{osname})...")
    install(file)
    print(f" - zig {VERSION} ({arch}/{osname})")

    DEST.rename(ROOT)

if __name__ == "__main__":
    main()

import os
import platform
import shutil
import sys
import tarfile
import time
from functools import wraps
from pathlib import Path
from urllib.error import HTTPError
from urllib.request import Request, urlopen

from versions import CLANG_VERSIONS

CLANG_CUDA_MAX = {"128": "19", "129": "19", "130": "20", "134": "22"}

ROOT = Path.cwd() / "deps" / "clang"
DEST = ROOT.with_suffix(".tmp")

URL = "https://github.com/llvm/llvm-project/releases/download/llvmorg-{version}/{file}"

ASSETS = {
    ("linux",   "x86_64"):  ["LLVM-{version}-Linux-X64.tar.xz"],
    ("linux",   "aarch64"): ["LLVM-{version}-Linux-ARM64.tar.xz", "clang+llvm-{version}-aarch64-linux-gnu.tar.xz"],
    ("windows", "x86_64"):  ["clang+llvm-{version}-x86_64-pc-windows-msvc.tar.xz"],
    ("windows", "aarch64"): ["clang+llvm-{version}-aarch64-pc-windows-msvc.tar.xz"],
}

def retry(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        for i in reversed(range(5)):
            try:
                return func(*args, **kwargs)
            except Exception:
                if not i:
                    raise
                time.sleep(10)
    return wrapper

def detect_arch():
    machine = platform.machine().lower()
    if machine in ("x86_64", "amd64"):
        return "x86_64"
    if machine in ("aarch64", "arm64"):
        return "aarch64"
    return machine

def detect_os():
    system = platform.system().lower()
    return {"darwin": "macos"}.get(system, system)

def resolve_version(arg):
    if arg == "cuda":
        # newest clang the installed CUDA accepts as nvcc host compiler
        code = os.getenv("CUDA_CODE")
        if code not in CLANG_CUDA_MAX:
            codes = ", ".join(sorted(CLANG_CUDA_MAX))
            sys.exit(f"Unknown CUDA_CODE '{code}' (expected one of: {codes})")
        arg = CLANG_CUDA_MAX[code]
    if arg in CLANG_VERSIONS:
        return CLANG_VERSIONS[arg]
    if all(p.isdigit() for p in arg.split(".")) and len(arg.split(".")) == 3:
        return arg
    known = ", ".join(f"{k} -> {v}" for k, v in sorted(CLANG_VERSIONS.items()))
    sys.exit(f"Unknown clang version '{arg}' (expected 'cuda', a major in {known} or a full X.Y.Z version)")

def asset_url(version, os_name, arch):
    if (os_name, arch) not in ASSETS:
        sys.exit(f"Unsupported platform: {os_name}/{arch}")
    for file in ASSETS[(os_name, arch)]:
        file = file.format(version=version).replace("+", "%2B")
        url = URL.format(version=version, file=file)
        try:
            with fetch(Request(url, method="HEAD")) as r:
                if r.status == 200:
                    return url
        except HTTPError:
            continue
    sys.exit(f"No clang {version} release asset found for {os_name}/{arch}")

def fetch(req):
    return urlopen(Request(req.full_url, headers={"User-Agent": "curl/8.0"}, method=req.get_method()), timeout=120)

@retry
def install_tar(url):
    def members(tar):
        for member in tar:
            parts = Path(member.name).parts
            if len(parts) > 1:
                member.name = str(Path(*parts[1:]))
                yield member

    with fetch(Request(url)) as r:
        with tarfile.open(fileobj=r, mode="r|*") as tar:
            tar.extractall(DEST, members=members(tar), filter="tar")

def main():
    if len(sys.argv) < 2:
        sys.exit("usage: install-clang.py <cuda|major|X.Y.Z> [arch] [os]")
    version = resolve_version(sys.argv[1])
    arch = sys.argv[2] if len(sys.argv) >= 3 else detect_arch()
    os_name = sys.argv[3] if len(sys.argv) >= 4 else detect_os()

    url = asset_url(version, os_name, arch)

    shutil.rmtree(DEST, ignore_errors=True)
    DEST.mkdir(parents=True)

    print(f"Installing Clang {version} ({os_name}-{arch})...")
    install_tar(url)
    print(f" - clang {version} ({os_name}-{arch})")

    shutil.rmtree(ROOT, ignore_errors=True)
    DEST.rename(ROOT)

if __name__ == "__main__":
    main()

if (!$LLAMA_BUCKET) { $LLAMA_BUCKET = $env:LLAMA_BUCKET }
if (!$LLAMA_BUCKET) { $LLAMA_BUCKET = "ggml-org/install.sh" }
$REPO = "https://huggingface.co/buckets/$LLAMA_BUCKET/resolve"
$WebParams = @{}

if ($env:HF_TOKEN) {
    $WebParams["Headers"] = @{ "Authorization" = "Bearer $env:HF_TOKEN" }
}

function Die {
    param([string[]]$Messages)
    $Messages | % { [Console]::Error.WriteLine($_) }
    exit 111
}

function Download {
    param($FILE, [string[]]$URL)
    if (Test-Path "$DIR\$FILE") {
        return $true
    }
    Write-Host "Downloading $FILE..."
    foreach ($U in $URL) {
        try {
            if ($U -like "*.zst") {
                if (!(Download "unzstd.exe" "$ARCH/windows/unzstd.exe")) { return $false }
                Invoke-RestMethod "$REPO/$LLAMA_VERSION/$U" -OutFile "$DIR\tmp.zst" @WebParams
                Start-Process -FilePath "$DIR\unzstd.exe" -RedirectStandardInput "$DIR\tmp.zst" -RedirectStandardOutput "$DIR\$FILE" -NoNewWindow -Wait
                Remove-Item "$DIR\tmp.zst"
            } else {
                Invoke-RestMethod "$REPO/$LLAMA_VERSION/$U" -OutFile "$DIR\$FILE" @WebParams
            }
            if (Test-Path "$DIR\$FILE") { return $true }
        } catch {
            if ($U -eq $URL[-1]) { [Console]::Error.WriteLine("Failed to download") }
        }
    }
    return $false
}

function ProbeCUDA {
    if ($env:SKIP_CUDA) { return }
    "Probing CUDA..."
    if (!(Download "cuda-probe.exe" "$ARCH/windows/cuda/probe/probe.exe.zst")) { return }
    $CONFIG = & "$DIR\cuda-probe.exe" 2>$null
    if ($LASTEXITCODE -eq 5) {
        "NVIDIA GPU detected, but the CUDA Toolkit is not installed."
        "To enable CUDA acceleration, install it from:"
        ""
        "  https://developer.nvidia.com/cuda-downloads"
        ""
        "or run:"
        ""
        "  winget install Nvidia.CUDA"
        ""
        return
    }
    if ($LASTEXITCODE) { return }
    "Found: $CONFIG"
    $parts  = -split $CONFIG
    $CONFIG = $parts[0]
    $MAJOR  = $parts[1]
    Download "llama.exe" "$ARCH/windows/cuda/$MAJOR/$CONFIG/llama-app.exe.zst" | Out-Null
}

function ProbeROCm {
    if ($env:SKIP_ROCM) { return }
    "Probing ROCm..."
    if (!(Download "rocm-probe.exe" "$ARCH/windows/rocm/probe/probe.exe.zst")) { return }
    $CONFIG = & "$DIR\rocm-probe.exe" 2>$null
    if ($LASTEXITCODE -eq 5) {
        "AMD GPU detected, but the HIP SDK is not installed."
        "To enable ROCm acceleration, install it from:"
        ""
        "  https://rocm.docs.amd.com/projects/install-on-windows/en/latest/install/install.html"
        ""
        return
    }
    if ($LASTEXITCODE) { return }
    "Found: $CONFIG"
    Download "llama.exe" "$ARCH/windows/rocm/$CONFIG/llama-app.exe.zst" | Out-Null
}

function ProbeVulkan {
    if ($env:SKIP_VULKAN) { return }
    "Probing Vulkan..."
    if (!(Download "vulkan-probe.exe" @("$ARCH/windows/vulkan/probe/probe.exe.zst", "$ARCH/windows/vulkan/probe/probe.zst"))) { return }
    if (!(Download "featcode.exe" "$ARCH/windows/featcode.exe")) { return }
    & "$DIR\vulkan-probe.exe" 2>$null
    if ($LASTEXITCODE) { return }
    $CONFIG = & "$DIR\featcode.exe" 2>$null
    & "$DIR\featcode.exe" $CONFIG 2>$null | % { "Found: $_" }
    Download "llama.exe" @("$ARCH/windows/vulkan/$CONFIG/llama-app.exe.zst", "$ARCH/windows/vulkan/$CONFIG/llama-app.zst") | Out-Null
}

function ProbeCPU {
    "Probing CPU..."
    if (!(Download "featcode.exe" "$ARCH/windows/featcode.exe")) { return }
    $CONFIG = & "$DIR\featcode.exe" 2>$null
    & "$DIR\featcode.exe" $CONFIG 2>$null | % { "Found: $_" }
    Download "llama.exe" @("$ARCH/windows/cpu/$CONFIG/llama-app.exe.zst", "$ARCH/windows/cpu/$CONFIG/llama-app.zst") | Out-Null
}

function Main {
    switch ($env:PROCESSOR_ARCHITECTURE) {
        "ARM64" { $ARCH = "aarch64" }
        "AMD64" { $ARCH = "x86_64"  }
        default { Die "Arch not supported" }
    }

    if (!$LLAMA_VERSION) { $LLAMA_VERSION = $env:LLAMA_VERSION }
    if (!$LLAMA_VERSION) { $LLAMA_VERSION = Invoke-RestMethod "$REPO/latest" @WebParams }
    if (!$LLAMA_VERSION) { Die "No version found" }
    "Version: $LLAMA_VERSION"

    $INSTALL_DIR = Join-Path $env:LOCALAPPDATA "Microsoft\WindowsApps"
    $DIR = Join-Path $env:LOCALAPPDATA "llama-app"
    Remove-Item $DIR -Recurse -Force 2>$null
    New-Item -Path $DIR -Force -ItemType "Directory" | Out-Null

    if (!(Test-Path "$DIR\llama.exe")) { ProbeCUDA   }
    if (!(Test-Path "$DIR\llama.exe")) { ProbeROCm   }
    if (!(Test-Path "$DIR\llama.exe")) { ProbeVulkan }
    if (!(Test-Path "$DIR\llama.exe")) { ProbeCPU    }
    if (!(Test-Path "$DIR\llama.exe")) {
        Die "No prebuilt llama binary is available for your system." `
            "Please compile llama.cpp from source instead."
    }
    if ($env:SKIP_INSTALL) {
        "Installation skipped, SKIP_INSTALL is set"
        return
    }
    $Version = (& "$DIR\llama.exe" version 2>&1) | Out-String

    if ($LASTEXITCODE) {
        Die "Downloaded llama binary failed to run"
    }
    $BUILD = $LLAMA_VERSION -replace "^b", ""
    if ("$Version" -notlike "$LLAMA_VERSION-*" -and "$Version" -notlike "*build $BUILD*") {
        Die "Version mismatch: expected $LLAMA_VERSION, got $Version"
    }
    if (Test-Path "$INSTALL_DIR\llama.exe") {
        Move-Item "$INSTALL_DIR\llama.exe" "$DIR\llama.exe.old" -Force
    }
    Move-Item "$DIR\llama.exe" "$INSTALL_DIR\llama.exe" -Force
    Remove-Item $DIR -Recurse -Force 2>$null

    "Installation completed successfully"
    ""
    "Please run the following command to start it:"
    ""
    "  llama.exe serve"
    ""
}

